autoch = [
  dict(id='A-JKS-208', src='JKS-208', nom="Rivière Kansas, en face de Muncie : Kansas — White Plume, L'Éveillé et Le Petit Maigre au camp de Jules de Mun (juillet-août 1816)",
       theme='rencontre', date='1816-07-11/1816-08-04', lon=-94.72, lat=39.08, cert='a',
       nations=['Kansas (Kaws)'], aires=['Plaines'], francophones=['Jules de Mun', 'Louis Gonville'],
       description="En juillet 1816, le brave kansa White Plume (Plume Blanche), rencontré à Fire Prairie, offre à Jules de Mun de l'accompagner jusqu'au-delà de sa tribu et d'aller l'attendre avec ses chevaux sur la rivière Kansas. Le 13 juillet, il visite le camp du traitant avec deux autres Kansas, deux Petits Osages et leurs femmes ; le 14, il revient tenir conseil et demander du tabac. Le 1er août, un Kansa part avec un Chaouanon porter une lettre de De Mun à Chouteau. Le 3 août, un chef que les Français appellent Le Petit Maigre et un Kansa nommé L'Éveillé, élevé un temps à Saint-Louis et parlant bien français, apportent le récit du combat de Chouteau contre les Pawnees sur l'Arkansas. Les Kansas servent ainsi de messagers et d'informateurs aux traitants de Saint-Louis.",
       note="D'après le journal de De Mun cité par Johnson, p. 142-144. White Plume devient plus tard chef principal (n. 855)."),
  dict(id='A-JKS-212', src='JKS-212', nom="Agence kansa : Kansas — White Plume reçoit Bonneville dans sa maison de pierre (mai 1832)",
       theme='rencontre', date='1832-05-13/1832-05-15', lon=-95.33, lat=39.07, cert='a',
       nations=['Kansas (Kaws)'], aires=['Plaines'], francophones=['Benjamin Louis Eulalie de Bonneville', 'Michel Sylvestre Cerré'],
       description="En mai 1832, le chef kansa White Plume habite près de l'agence une grande maison de pierre bâtie par ordre du gouvernement américain, mais meublée à l'indienne. Il accueille le capitaine Bonneville, lui raconte assis sur sa robe de bison les exploits de sa tribu contre les Pawnees et l'accompagne une journée de marche, passant la nuit dans son camp. Les Kansas se pressent autour des vingt chariots, spectacle inhabituel, examinent tout et posent mille questions. Sur la route, la caravane ne croise qu'un guerrier kansa revenant d'une expédition solitaire avec un scalp pawnee.",
       note="D'après Irving, Adventures of Captain Bonneville, cité par Johnson, p. 157-159."),
  dict(id='A-JKS-218', src='JKS-218', nom="Comté de Clay (Missouri) : Kansas — la bande d'American Chief chez Grand Louis Bertholet (juillet 1823)",
       theme='rencontre', date='1823-07-04/1823-07-05', lon=-94.58, lat=39.14, cert='a',
       nations=['Kansas (Kaws)'], aires=['Plaines'], francophones=['Louis Bertholet dit Grand Louis', 'Louis Caillou'],
       description="Le 4 juillet 1823, le chef kansa American Chief (Wakanze-re) campe avec sa bande sur la rive opposée du Missouri, en face de la cabane du traitant Grand Louis Bertholet, à trois milles en aval de l'embouchure de la Kansas. Il invite le prince Paul de Wurtemberg et ses compagnons à le rejoindre. Le lendemain, les Kansas viennent à la cabane de Bertholet et l'on échange des présents. Le surlendemain, le bateau du prince repart vers l'amont et longe les anciens villages kansas, le « Village of the Twelve » et le « Village of the Twenty-four ».",
       note="D'après le récit du prince Paul de Wurtemberg cité par Johnson, p. 180."),
]
